
CREATE TABLE jugadores(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(50),uuid VARCHAR(100),skin TEXT,pais VARCHAR(50));
CREATE TABLE speedruns(id INT AUTO_INCREMENT PRIMARY KEY,id_jugador INT,categoria VARCHAR(50),tiempo VARCHAR(20),fecha DATE,version VARCHAR(20));
CREATE TABLE pvp(id INT AUTO_INCREMENT PRIMARY KEY,id_jugador INT,victorias INT,derrotas INT,kills INT,racha INT);
CREATE TABLE mods(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100),autor VARCHAR(100),version VARCHAR(20),descargas BIGINT,url TEXT);
CREATE TABLE servidores(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100),ip VARCHAR(100),pais VARCHAR(50),jugadores INT,estado VARCHAR(20));
CREATE TABLE records_mundiales(id INT AUTO_INCREMENT PRIMARY KEY,jugador VARCHAR(100),tiempo VARCHAR(20),categoria VARCHAR(50),fecha DATE);
